"""
OC-002: OpenClaw Workflow Adapter.
Defines the entrypoints for cron-driven research and deployment workflows.
"""
from typing import Any, Dict

class OpenClawWorkflowAdapter:
    def __init__(self):
        # Pinning upstream OpenClaw version/ref
        self.upstream_ref = "github.com/openclaw/openclaw-core"
        self.upstream_version = "v0.1.0-alpha" # Example pin

    def create_ingest_payload(self, source_url: str, spec_hints: Dict[str, Any]) -> Dict[str, Any]:
        """
        Maps raw research source to OpenClaw's ingestion workflow parameters.
        """
        return {
            "workflow": "research_ingestion",
            "params": {
                "source": source_url,
                "depth": "full",
                "metadata_hints": spec_hints
            },
            "governance": {
                "target_state": "draft",
                "adapter_version": self.upstream_version
            }
        }

    def create_deploy_payload(self, strategy_id: str, version: str, mode: str) -> Dict[str, Any]:
        """
        Maps a registry artifact to an OpenClaw deployment workflow.
        """
        return {
            "workflow": "strategy_deployment",
            "params": {
                "strategy_id": strategy_id,
                "version": version,
                "execution_mode": mode # paper or live
            }
        }

